/**
 * Parse SERP Data (네이버판) — 네이버 검색 상위 글을 프롬프트용으로 정리
 * Mode: runOnceForEachItem
 * 입력: Naver Search (SerpAPI) 노드 응답 (engine=naver, web_results — 블로그·카페·웹 문서)
 *   네이버 검색 API 발급이 막혀 SerpAPI를 쓴다. SerpAPI는 블로그 전용(where=blog)을 지원하지 않는다.
 * 출력: 시트 행 + serp_text, top_posts, search_ok
 * 노드 이름은 'Parse SERP Data' 그대로 둔다 — URL Validation이 이 이름으로 serp_urls를 읽는다.
 */

const TOP_LIMIT = 5;

function stripTags(value) {
  return String(value || '')
    .replace(/<[^>]+>/g, '')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&')
    .trim();
}

function summarizeNaverResults(response, limit = TOP_LIMIT) {
  const items = response && Array.isArray(response.web_results) ? response.web_results : [];
  const topPosts = items.slice(0, limit).map((it) => ({
    title: stripTags(it.title),
    description: stripTags(it.snippet),
    link: it.link || '',
  }));
  const serpText = topPosts
    .map((p, i) => `${i + 1}. ${p.title}\n   ${p.description}`)
    .join('\n');
  return { topPosts, serpText };
}

if (typeof $input === 'undefined') {
  module.exports = { stripTags, summarizeNaverResults };
  return;
}

const summary = summarizeNaverResults($input.item.json);
const sheetData = $('Sheets Read (Status=대기)').item.json;

return {
  json: {
    ...sheetData,
    serp_text: summary.serpText || '(네이버 검색 결과 없음)',
    top_posts: summary.topPosts,
    search_ok: summary.topPosts.length > 0,
    serp_urls: [],      // 경쟁 블로그 글은 인용하지 않는다
    official_urls: [],  // Fetch Official Docs는 건너뛴다
  },
};

/**
 * Build LLM Request — provider별 URL/headers/body 생성
 * 입력: system_prompt, user_message, _llm_purpose(optional)
 * 출력: _llm_url, _llm_headers, _llm_body, _llm_provider + 원본 데이터 패스스루
 */

const provider = $env.LLM_PROVIDER || 'gemini';
const systemPrompt = $input.item.json.system_prompt;
const userMessage = $input.item.json.user_message;
const purpose = $input.item.json._llm_purpose || 'content_gen';

const PROVIDERS = {
  gemini: {
    url: `https://generativelanguage.googleapis.com/v1beta/models/gemini-3.6-flash:generateContent`,
    // API 키는 n8n Credential(Header Auth, x-goog-api-key)이 주입한다 —
    // URL/헤더에 넣으면 실행 기록에 평문으로 남는다
    headers: { 'content-type': 'application/json' },
    body: (sys, user, opts) => {
      const payload = {
        contents: [{ role: 'user', parts: [{ text: user }] }],
        systemInstruction: { parts: [{ text: sys }] },
        generationConfig: { maxOutputTokens: opts.maxTokens, temperature: opts.temperature },
      };
      // Search Grounding: 콘텐츠 생성 시 Google 검색으로 실시간 팩트 기반 응답
      if (opts.useSearchGrounding) {
        payload.tools = [{ google_search: {} }];
      }
      return payload;
    },
  },
  claude: {
    url: 'https://api.anthropic.com/v1/messages',
    // API 키는 n8n Credential(Header Auth, x-api-key)이 주입한다.
    // LLM_PROVIDER=claude로 바꿀 때는 LLM Request 노드 2개의 자격증명을
    // 'Claude API Key (Header)'로 함께 바꿔야 한다.
    headers: {
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json',
    },
    body: (sys, user, opts) => ({
      model: opts.model || 'claude-sonnet-4-5-20250514',
      max_tokens: opts.maxTokens,
      temperature: opts.temperature,
      system: sys,
      messages: [{ role: 'user', content: user }],
    }),
  },
};

const config = PROVIDERS[provider];
if (!config) throw new Error(`지원하지 않는 LLM provider: ${provider}`);

const opts = purpose === 'verification'
  ? { maxTokens: 4096, temperature: 0, model: 'claude-haiku-4-5-20251001' }
  : { maxTokens: 32768, temperature: 0.7, useSearchGrounding: true };

return {
  json: {
    _llm_url: config.url,
    _llm_headers: config.headers,
    _llm_body: config.body(systemPrompt, userMessage, opts),
    _llm_provider: provider,
    ...Object.fromEntries(
      Object.entries($input.item.json).filter(([k]) => !k.startsWith('_llm'))
    ),
  }
};

/**
 * Normalize LLM Response — provider별 응답에서 텍스트 추출
 * Gemini: candidates[0].content.parts[0].text
 * Claude: content[0].text
 */

const provider = $input.item.json._llm_provider
  || $env.LLM_PROVIDER
  || 'gemini';

let text;
const data = $input.item.json;

if (provider === 'gemini') {
  const parts = data.candidates?.[0]?.content?.parts || [];
  // 추론 모델 + Search Grounding 응답은 텍스트가 여러 part로 분할될 수 있음
  text = parts.filter(p => !p.thought && typeof p.text === 'string').map(p => p.text).join('');
  if (!text) {
    throw new Error(`Gemini 빈 응답 (finishReason: ${data.candidates?.[0]?.finishReason || 'unknown'})`);
  }
} else if (provider === 'claude') {
  text = data.content[0].text;
} else {
  throw new Error(`지원하지 않는 provider 응답: ${provider}`);
}

return { json: { text, _llm_provider: provider } };

/**
 * Node 6: LLM 응답 JSON 파싱 + 필수 필드 검증
 * Mode: runOnceForEachItem
 * 입력: 정규화된 LLM 응답 (text)
 * 출력: 파싱된 JSON 또는 에러
 *
 * LLM이 생성한 JSON의 일반적 문제를 자동 복구:
 * - 문자열 내 이스케이프되지 않은 " (YAML, 코드블록 등)
 * - 제어 문자 (raw newline/tab)
 * - 유효하지 않은 이스케이프 시퀀스 (\g, \e 등)
 */

const raw = $input.item.json.text;

// 알려진 최상위 JSON 필드 목록 (구조적 키 판별에 사용)
const TOP_LEVEL_KEYS = new Set([
  'title', 'url_slug', 'content', 'meta_description', 'faq_schema',
  'references', 'internal_link_keywords', 'tags', '_warning',
]);

// === Step 1: JSON 블록 추출 ===
let jsonStr;
const fenceStart = raw.indexOf('```json');
if (fenceStart !== -1) {
  const contentStart = raw.indexOf('\n', fenceStart);
  const fenceEnd = raw.lastIndexOf('```');
  if (contentStart !== -1 && fenceEnd > fenceStart + 7) {
    jsonStr = raw.substring(contentStart + 1, fenceEnd).trim();
  }
}
if (!jsonStr) {
  const match = raw.match(/(\{[\s\S]*\})/);
  if (!match) {
    throw new Error("JSON 추출 실패: " + raw.substring(0, 200));
  }
  jsonStr = match[1];
}

// === Step 2: Lenient JSON repair ===
// 구조적 파싱으로 이스케이프되지 않은 " 와 제어 문자를 자동 복구
function repairJson(str) {
  const VALID_ESCAPES = '"\\\/bfnrtu';
  let result = '';
  let i = 0;

  function skipWS() {
    while (i < str.length && /\s/.test(str[i])) { result += str[i++]; }
  }

  function parseValue() {
    skipWS();
    if (i >= str.length) return;
    if (str[i] === '"') parseString();
    else if (str[i] === '{') parseObject();
    else if (str[i] === '[') parseArray();
    else parseLiteral();
  }

  function parseString() {
    result += str[i++]; // opening "

    while (i < str.length) {
      const ch = str[i];

      // 이스케이프 시퀀스
      if (ch === '\\' && i + 1 < str.length) {
        const next = str[i + 1];
        if (VALID_ESCAPES.includes(next)) {
          result += ch + next;
        } else {
          // 유효하지 않은 이스케이프 → 백슬래시 이중 이스케이프
          result += '\\\\' + next;
        }
        i += 2;
        continue;
      }

      // 큰따옴표: 구조적 종료인지 content 내 인용부호인지 판단
      if (ch === '"') {
        // 다음 비공백 문자로 판단
        let peek = i + 1;
        while (peek < str.length && /[\s\n\r\t]/.test(str[peek])) peek++;

        if (peek >= str.length || ',:]}'.indexOf(str[peek]) !== -1) {
          // 구조적 종료: 뒤에 , ] } : 또는 EOF
          result += '"';
          i++;
          return;
        } else if (str[peek] === '"') {
          // 다음도 " → 다음 "..." 사이가 유효한 JSON 키인지 검증
          let j = peek + 1;
          let candidateKey = '';
          while (j < str.length && str[j] !== '"' && str[j] !== ':') {
            candidateKey += str[j];
            j++;
          }
          // 조건 강화: (1) " 로 닫혀야 하고 (2) 그 뒤에 : 이 있고
          // (3) 키가 유효한 JSON 키 패턴 (짧고, 알파벳/언더스코어)
          // (4) 알려진 최상위 필드명이어야 구조적 종료로 판단
          if (j < str.length && str[j] === '"') {
            let k = j + 1;
            while (k < str.length && /[\s]/.test(str[k])) k++;
            if (k < str.length && str[k] === ':'
                && candidateKey.length > 0 && candidateKey.length < 30
                && /^[a-zA-Z_][\w_]*$/.test(candidateKey)
                && TOP_LEVEL_KEYS.has(candidateKey)) {
              // "value" "known_key": → 쉼표 누락이지만 구조적 종료
              result += '"';
              i++;
              return;
            }
          }
          // 유효한 키가 아님 → content 내 인용부호
          result += '\\"';
          i++;
          continue;
        } else {
          // 뒤에 일반 문자 → content 내 이스케이프되지 않은 인용부호
          result += '\\"';
          i++;
          continue;
        }
      }

      // 제어 문자
      const code = ch.charCodeAt(0);
      if (code <= 0x1f) {
        if (code === 0x0a) result += '\\n';
        else if (code === 0x0d) result += '\\r';
        else if (code === 0x09) result += '\\t';
        i++;
        continue;
      }

      result += ch;
      i++;
    }
  }

  function parseObject() {
    result += str[i++]; // {
    skipWS();
    let first = true;
    while (i < str.length && str[i] !== '}') {
      if (!first) {
        if (str[i] === ',') result += str[i++];
        // 쉼표 누락: "}" 아닌 다른 문자가 오면 쉼표 삽입
        else {
          skipWS();
          if (i < str.length && str[i] === '"') result += ',';
        }
      }
      first = false;
      skipWS();
      if (i >= str.length || str[i] === '}') break;
      parseString(); // key
      skipWS();
      if (i < str.length && str[i] === ':') result += str[i++];
      parseValue();   // value
      skipWS();
    }
    if (i < str.length && str[i] === '}') result += str[i++];
  }

  function parseArray() {
    result += str[i++]; // [
    skipWS();
    let first = true;
    while (i < str.length && str[i] !== ']') {
      if (!first) {
        if (str[i] === ',') result += str[i++];
        else {
          skipWS();
          if (i < str.length && str[i] !== ']') result += ',';
        }
      }
      first = false;
      skipWS();
      if (i >= str.length || str[i] === ']') break;
      parseValue();
      skipWS();
    }
    if (i < str.length && str[i] === ']') result += str[i++];
  }

  function parseLiteral() {
    // number, boolean, null
    while (i < str.length && /[^\s,\]}\[]/.test(str[i])) {
      result += str[i++];
    }
  }

  parseValue();
  return result;
}

// === Step 2.5: 필드 경계 기반 추출 (3차 폴백) ===
// 최상위 키 위치를 정규식으로 찾아 값을 개별 추출 → 안전하게 이스케이프
function extractByFieldBoundary(str) {
  // 최상위 키의 시작 위치 찾기: "key" 다음에 : 이 오는 패턴
  // 들여쓰기 기반 필터: 최상위 키는 보통 2~4칸 들여쓰기 또는 줄 시작
  const keyPattern = /(?:^|[\n{,])\s*"(title|content|meta_description|faq_schema|references|internal_link_keywords)"\s*:/g;
  const seen = new Set();
  const positions = [];
  let m;
  while ((m = keyPattern.exec(str)) !== null) {
    // 각 키의 첫 번째 매치만 사용 (중복 방지)
    if (seen.has(m[1])) continue;
    seen.add(m[1]);
    // 실제 키 시작 위치 보정 (prefix 문자 제외)
    const keyStart = str.indexOf('"' + m[1] + '"', m.index);
    const fullMatch = '"' + m[1] + '"';
    let vs = keyStart + fullMatch.length;
    while (vs < str.length && /[\s:]/.test(str[vs])) vs++;
    positions.push({ key: m[1], start: keyStart, valueStart: vs });
  }
  if (positions.length === 0) {
    throw new Error("필드 경계를 찾을 수 없음");
  }
  // 키 위치 순서로 정렬
  positions.sort((a, b) => a.start - b.start);

  const obj = {};
  for (let pi = 0; pi < positions.length; pi++) {
    const pos = positions[pi];
    // 값 영역: 현재 valueStart ~ 다음 키의 start (또는 문자열 끝)
    const valueEnd = pi + 1 < positions.length ? positions[pi + 1].start : str.length;
    let rawValue = str.substring(pos.valueStart, valueEnd).trim();

    // 후행 쉼표 제거
    if (rawValue.endsWith(',')) rawValue = rawValue.slice(0, -1).trim();
    // 마지막 필드일 때 닫는 } 제거
    if (pi === positions.length - 1 && rawValue.endsWith('}')) {
      rawValue = rawValue.slice(0, -1).trim();
      if (rawValue.endsWith(',')) rawValue = rawValue.slice(0, -1).trim();
    }

    // 배열/객체 값은 직접 파싱 시도
    if (rawValue.startsWith('[') || rawValue.startsWith('{')) {
      try {
        obj[pos.key] = JSON.parse(rawValue);
        continue;
      } catch (_) {
        // 배열/객체 파싱 실패 → 문자열 repair 시도
        try {
          obj[pos.key] = JSON.parse(repairJson(rawValue));
          continue;
        } catch (__) {
          // 배열 필드는 빈 배열로 초기화 (문자열로 저장 방지)
          if (['faq_schema', 'references', 'internal_link_keywords'].includes(pos.key)) {
            obj[pos.key] = [];
            continue;
          }
          // 그 외 → 문자열로 저장
        }
      }
    }

    // 문자열 값: 앞뒤 " 제거 후 내부 " 이스케이프
    if (rawValue.startsWith('"')) rawValue = rawValue.slice(1);
    if (rawValue.endsWith('"')) rawValue = rawValue.slice(0, -1);
    // 이미 이스케이프된 \" 보존, 나머지 " 이스케이프
    rawValue = rawValue.replace(/\\"/g, '<<ESC_Q>>');
    rawValue = rawValue.replace(/"/g, '\\"');
    rawValue = rawValue.replace(/<<ESC_Q>>/g, '\\"');
    // 제어 문자 이스케이프
    rawValue = rawValue.replace(/[\x00-\x1f]/g, (c) => {
      if (c === '\n') return '\\n';
      if (c === '\r') return '\\r';
      if (c === '\t') return '\\t';
      return '';
    });

    try {
      obj[pos.key] = JSON.parse('"' + rawValue + '"');
    } catch (_) {
      // 최후 수단: JSON.parse 없이 이스케이프만 직접 되돌린다.
      // 그대로 두면 본문에 리터럴 \n 이 남아 마크다운 변환기가 문단·헤딩을
      // 인식하지 못하고 한 덩어리로 렌더링된다(2026-09-22 발행글 539·540).
      obj[pos.key] = rawValue
        .replace(/\\u([0-9a-fA-F]{4})/g, (_m, hex) => String.fromCharCode(parseInt(hex, 16)))
        .replace(/\\n/g, '\n')
        .replace(/\\r/g, '\r')
        .replace(/\\t/g, '\t')
        .replace(/\\"/g, '"')
        .replace(/\\\\/g, '\\');
    }
  }

  return obj;
}

// === Step 3: 파싱 ===
let parsed;

// 1차: 그대로 파싱
try {
  parsed = JSON.parse(jsonStr);
} catch (e1) {
  // 2차: lenient repair 후 파싱
  try {
    const repaired = repairJson(jsonStr);
    parsed = JSON.parse(repaired);
  } catch (e2) {
    // 3차: 필드 경계 추출 (content 필드의 unescaped quote 대응)
    try {
      parsed = extractByFieldBoundary(jsonStr);
    } catch (e3) {
      throw new Error("JSON 파싱 실패: " + e1.message
        + " | repair 후: " + e2.message
        + " | boundary 후: " + e3.message);
    }
  }
}

// === Step 4: 필수 필드 검증 ===
const required = ["title", "content", "meta_description", "faq_schema",
                  "references", "internal_link_keywords"];
const missing = required.filter(f => !parsed[f]);
if (missing.length > 0) {
  throw new Error("필수 필드 누락: " + missing.join(", "));
}

// meta_description 길이 검증 (120~155자)
const metaLen = parsed.meta_description.length;
if (metaLen < 120 || metaLen > 155) {
  parsed._warning = `meta_description 길이: ${metaLen}자 (권장 120~155자)`;
}

// faq_schema 형식 검증
if (!Array.isArray(parsed.faq_schema) || parsed.faq_schema.length === 0) {
  throw new Error("faq_schema가 비어있거나 배열이 아닙니다");
}
const FAQ_PLACEHOLDER = /참조|참고하세요|확인하세요|문서를 보세요|홈페이지를 방문/;
for (const faq of parsed.faq_schema) {
  if (!faq.question || !faq.answer) {
    throw new Error("faq_schema 항목에 question/answer 누락");
  }
  if (faq.answer.length < 80) {
    throw new Error(`FAQ 답변 길이 부족: ${faq.answer.length}자 (최소 80자)`);
  }
  if (FAQ_PLACEHOLDER.test(faq.answer) && faq.answer.length < 120) {
    throw new Error(`FAQ 답변이 플레이스홀더: "${faq.answer.slice(0, 50)}..."`);
  }
}

// references 플레이스홀더 필터링
if (Array.isArray(parsed.references)) {
  parsed.references = parsed.references.filter(ref => {
    if (typeof ref !== 'string') return false;
    if (ref.length < 10) return false;
    if (/^참조|^참고|^확인|^검색/.test(ref) && !ref.startsWith('http')) return false;
    return true;
  });
}

// 본문 길이 검증 (프롬프트 유형별 최소 글자 수)
const promptType = $('Route Prompt (A/B/C)').item.json.prompt_type || 'A';
const LENGTH_RULES = {
  'A': { min: 1500 },
  'B': { min: 2000 },
  'C': { min: 2000 }
};
const rule = LENGTH_RULES[promptType] || LENGTH_RULES['A'];
if (parsed.content.length < rule.min) {
  throw new Error(`본문 길이 부족: ${parsed.content.length}자 (최소 ${rule.min}자, 유형: ${promptType})`);
}

return { json: parsed };

/**
 * Validate Structure (네이버판) — 네이버 규칙을 코드로 검사
 * Mode: runOnceForEachItem
 * 입력: Parse JSON Response 출력 (title, content, tags)
 * 출력: 입력 + structure_validation { passed, issues, stats }
 * 여기서 실패하면 Parse Verification Result가 LLM 점수와 무관하게 검수필요로 보낸다.
 */

const LIMITS = {
  minLength: 3000,
  minH2: 3,
  minKeywordCount: 1,
  maxKeywordCount: 6,
  maxExternalLinks: 3,
  maxParagraphChars: 300,
  maxCodeBlocks: 1,
  minTags: 5,
  maxTags: 15,
};

// 제목·표·목록·인용·코드는 문단 길이 검사에서 뺀다
const NON_PARAGRAPH = /^(#|\||-|\*|>|```|\d+\.\s)/;

function countOccurrences(text, word) {
  const needle = String(word || '').trim().toLowerCase();
  if (!needle) return 0;
  return String(text || '').toLowerCase().split(needle).length - 1;
}

function longParagraphs(content, maxChars) {
  return String(content || '')
    .split(/\n\s*\n/)
    .map((block) => block.trim())
    .filter((block) => block && !NON_PARAGRAPH.test(block))
    .filter((block) => block.length > maxChars);
}

function titleHasKeyword(title, keyword) {
  const squash = (s) => String(s || '').replace(/\s+/g, '').toLowerCase();
  const t = squash(title);
  if (t.includes(squash(keyword))) return true;
  const tokens = String(keyword || '').toLowerCase().split(/\s+/).filter(Boolean);
  return tokens.length > 0 && tokens.every((tok) => t.includes(tok));
}

// 소제목 아래 AI 사진 설명 — 블로그에 보이지 않으므로 길이·문단 검사에서 뺀다
// (src/domain/services/photo_markers.py SCENE_COMMENT와 같은 형식)
const SCENE_COMMENT = /<!--\s*사진:[\s\S]*?-->/g;

function validateNaverStructure({ title, content, keyword, tags }) {
  const text = String(content || '').replace(SCENE_COMMENT, '');
  const issues = [];
  const h2 = (text.match(/^## /gm) || []).length;
  const keywordCount = countOccurrences(text, keyword);
  const externalLinks = (text.match(/\]\(https?:\/\/[^)]+\)/g) || []).length;
  const codeBlocks = Math.floor((text.match(/^```/gm) || []).length / 2);
  const longOnes = longParagraphs(text, LIMITS.maxParagraphChars);
  const tagCount = Array.isArray(tags) ? tags.length : 0;

  if (text.length < LIMITS.minLength) issues.push(`본문 길이 부족: ${text.length}자 (최소 ${LIMITS.minLength}자)`);
  if (h2 < LIMITS.minH2) issues.push(`소제목(H2) 부족: ${h2}개 (최소 ${LIMITS.minH2}개)`);
  if (!titleHasKeyword(title, keyword)) issues.push('제목에 키워드 없음');
  if (keywordCount < LIMITS.minKeywordCount) issues.push('본문에 키워드 없음');
  if (keywordCount > LIMITS.maxKeywordCount) issues.push(`키워드 반복 과다: ${keywordCount}회 (최대 ${LIMITS.maxKeywordCount}회)`);
  if (externalLinks > LIMITS.maxExternalLinks) issues.push(`외부 링크 과다: ${externalLinks}개 (최대 ${LIMITS.maxExternalLinks}개)`);
  if (codeBlocks > LIMITS.maxCodeBlocks) issues.push(`코드 블록 과다: ${codeBlocks}개 (최대 ${LIMITS.maxCodeBlocks}개)`);
  if (longOnes.length > 0) issues.push(`긴 문단 ${longOnes.length}개 (문단당 최대 ${LIMITS.maxParagraphChars}자)`);
  if (tagCount < LIMITS.minTags || tagCount > LIMITS.maxTags) issues.push(`태그 수 ${tagCount}개 (${LIMITS.minTags}~${LIMITS.maxTags}개)`);

  return {
    passed: issues.length === 0,
    issues,
    stats: {
      length: text.length, h2, keyword_count: keywordCount, external_links: externalLinks,
      code_blocks: codeBlocks, long_paragraphs: longOnes.length, tags: tagCount,
    },
  };
}

if (typeof $input === 'undefined') {
  module.exports = { LIMITS, countOccurrences, longParagraphs, titleHasKeyword, validateNaverStructure };
  return;
}

const item = $input.item.json;
return {
  json: {
    ...item,
    structure_validation: validateNaverStructure({
      title: item.title,
      content: item.content,
      keyword: $('Route Prompt (A/B/C)').item.json.keyword || '',
      tags: item.tags,
    }),
  },
};

/**
 * Node 7a: URL 검증 — HTTP HEAD + SERP 교차 대조 + 죽은 URL 자동 제거
 * Mode: runOnceForEachItem
 *
 * 주의: serp_urls는 Normalize Response/Parse JSON에서 소실되므로
 *       $('Parse SERP Data') 노드에서 직접 참조한다.
 */

const helpers = this.helpers;
const item = $input.item.json;
const content = item.content || '';
const references = item.references || [];

// serp_urls는 파이프라인 중간에서 소실 → Parse SERP Data 노드에서 직접 참조
let serpUrls = [];
try {
  serpUrls = $('Parse SERP Data').item.json.serp_urls || [];
} catch { /* 노드 미존재 시 빈 배열 */ }

// URL 추출 (trailing punctuation 제거)
const urlRegex = /https?:\/\/[^\s\)\]"'<>]+/g;
const rawUrls = content.match(urlRegex) || [];
const contentUrls = rawUrls.map(u => u.replace(/[.,;:!?)]+$/, ''));

// 모든 고유 URL 수집 (content + references)
const allUrls = [...new Set([
  ...contentUrls,
  ...references.filter(r => r.startsWith('http')),
])];

const issues = [];
const deadUrls = [];
const serpMatched = [];
const serpUnmatched = [];

// SERP 도메인 추출 (교차 대조용)
const serpDomains = new Set();
for (const url of serpUrls) {
  try { serpDomains.add(new URL(url).hostname); } catch {}
}

/**
 * HTTP 검증 — try/catch 패턴 (axios 기반)
 * 성공(2xx) = 반환값 존재, 실패(4xx/5xx/타임아웃) = 예외 발생
 */
async function checkUrl(url) {
  // 형식 검증 (HTTP 스킵)
  if (url.includes('...') || url.includes(' ')) {
    return { url, status: 'broken_format' };
  }
  if (url.includes('contoso.com') || url.includes('example.com')) {
    return { url, status: 'placeholder' };
  }

  // HEAD 시도
  try {
    await helpers.httpRequest({
      method: 'HEAD',
      url: url,
      timeout: 5000,
    });
    return { url, status: 'ok' };
  } catch {
    // HEAD 실패 → GET 폴백 (일부 서버 HEAD 거부)
    try {
      await helpers.httpRequest({
        method: 'GET',
        url: url,
        timeout: 5000,
        maxContentLength: 1024,
      });
      return { url, status: 'ok' };
    } catch {
      return { url, status: 'dead' };
    }
  }
}

// 병렬 검증 (배치 5개)
const results = [];
for (let i = 0; i < allUrls.length; i += 5) {
  const batch = allUrls.slice(i, i + 5);
  const batchResults = await Promise.all(batch.map(checkUrl));
  results.push(...batchResults);
}

// 결과 분류
for (const r of results) {
  if (r.status === 'placeholder') continue;

  if (r.status === 'broken_format' || r.status === 'dead') {
    issues.push(`접근 불가: ${r.url}`);
    deadUrls.push(r.url);
  }

  // SERP 교차 대조
  try {
    const domain = new URL(r.url).hostname;
    if (serpDomains.has(domain)) {
      serpMatched.push(r.url);
    } else {
      serpUnmatched.push(r.url);
    }
  } catch {}
}

// 죽은 URL 제거: [텍스트](deadUrl) → 텍스트
let cleanedContent = content;
for (const deadUrl of deadUrls) {
  const escaped = deadUrl.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  cleanedContent = cleanedContent.replace(
    new RegExp(`\\[([^\\]]+)\\]\\(${escaped}\\)`, 'g'),
    '$1'
  );
}

// 죽은 URL을 references에서도 제거
const cleanedReferences = references.filter(ref => {
  if (!ref.startsWith('http')) return true;
  return !deadUrls.includes(ref);
});

const passed = deadUrls.length === 0;

return {
  json: {
    ...item,
    content: cleanedContent,
    references: cleanedReferences,
    url_validation: {
      passed,
      total_urls: allUrls.length,
      reachable: results.filter(r => r.status === 'ok').length,
      dead: deadUrls.length,
      serp_matched: serpMatched.length,
      serp_unmatched: serpUnmatched.length,
      issues,
    }
  }
};

/**
 * Node 7b: 코드 블록 기초 포맷 검사
 * 언어 태그 존재 여부, 닫히지 않은 블록 감지
 */

const content = $input.item.json.content;

const issues = [];

// 1. 코드 블록 추출 (열기/닫기 쌍)
const openBlocks = (content.match(/```/g) || []).length;
if (openBlocks % 2 !== 0) {
  issues.push("닫히지 않은 코드 블록 존재");
}

// 2. 언어 태그 없는 코드 블록 감지
const codeBlockRegex = /```(\w*)\n/g;
let match;
let blockCount = 0;
let noTagCount = 0;

while ((match = codeBlockRegex.exec(content)) !== null) {
  blockCount++;
  if (!match[1]) {
    noTagCount++;
  }
}

if (noTagCount > 0) {
  issues.push(`언어 태그 없는 코드 블록: ${noTagCount}/${blockCount}건`);
}

// 3. 허용 언어 태그 검증
const allowedLangs = [
  "powershell", "bash", "cmd", "python", "json", "xml", "yaml",
  "csharp", "javascript", "html", "sql", "text", "plaintext",
  "shell", "ps1", "bat",
];
const langRegex = /```(\w+)/g;
let langMatch;
while ((langMatch = langRegex.exec(content)) !== null) {
  const lang = langMatch[1].toLowerCase();
  if (!allowedLangs.includes(lang)) {
    issues.push(`비표준 언어 태그: ${langMatch[1]}`);
  }
}

const passed = issues.length === 0;

return {
  json: {
    ...$input.item.json,
    code_lint: {
      passed,
      block_count: blockCount,
      issues,
    }
  }
};

/**
 * Build Verify Request (네이버판) — 검증 프롬프트 + 상위 글 + 본문
 * Mode: runOnceForEachItem
 * VERIFY_PROMPT는 scripts/build_naver_workflow.py가 n8n/prompts/prompt_naver_h_verification.md로 채운다.
 */

const VERIFY_PROMPT = /*INJECT:VERIFY_PROMPT*/ "# 네이버 블로그 글 품질 검증\n\n당신은 네이버 블로그 글의 품질을 검증합니다. 아래 기준으로 평가하고 JSON 하나만 출력합니다.\n\n## 평가 항목\n- is_accurate: 사실 오류가 없는가 (버전, 가격, 기능 설명)\n- is_logical: 흐름이 자연스럽고 소제목과 내용이 맞는가\n- is_complete: 검색한 사람이 궁금해할 내용을 빠짐없이 다뤘는가\n- is_useful: 읽고 나서 바로 써먹을 수 있는가\n- is_in_depth: 뻔한 설명을 넘어 판단 기준과 주의점이 있는가\n- no_fabricated_experience: \"직접 써보니\", \"제가 해보니\" 같은 지어낸 1인칭 경험이 없으면 true. `[[직접 해 보니]]`로 시작하는 문단은 발행 전에 사람이 채울 자리 표시이므로 지어낸 경험으로 보지 않는다\n- natural_keyword_use: 키워드가 억지로 반복되거나 문장이 어색하게 비틀리지 않았으면 true\n- has_unique_info: 함께 준 \"네이버 검색 상위 글\"에 없는 정보가 1개 이상 있으면 true\n- mobile_readable: 문단이 짧고(2~3문장) 소제목·목록으로 훑어보기 쉬우면 true\n\n## 점수\nquality_score는 0~100이며 70점 이상이면 발행 가능한 수준입니다.\n평가 항목 중 하나라도 false면 quality_score는 69점 이하로 줍니다.\n\n## 출력 형식\nJSON 외 텍스트를 쓰지 않습니다. reason은 한국어 100자 이내입니다.\n\n{\"is_accurate\": true, \"is_logical\": true, \"is_complete\": true, \"is_useful\": true, \"is_in_depth\": true, \"no_fabricated_experience\": true, \"natural_keyword_use\": true, \"has_unique_info\": true, \"mobile_readable\": true, \"quality_score\": 85, \"reason\": \"사유\"}" /*END:VERIFY_PROMPT*/;

function buildVerifyMessage({ keyword, title, content, topPosts }) {
  const tops = (topPosts || []).map((p, i) => `${i + 1}. ${p.title} — ${p.description}`).join('\n');
  return `키워드: ${keyword}\n\n## 네이버 검색 상위 글\n${tops || '(없음)'}`
    + `\n\n## 검증할 글\n제목: ${title}\n본문:\n${content}`;
}

if (typeof $input === 'undefined') {
  module.exports = { VERIFY_PROMPT, buildVerifyMessage };
  return;
}

const item = $input.item.json;
return {
  json: {
    ...item,
    system_prompt: VERIFY_PROMPT,
    user_message: buildVerifyMessage({
      keyword: $('Route Prompt (A/B/C)').item.json.keyword || '',
      title: item.title || '',
      content: item.content || '',
      topPosts: $('Parse SERP Data').item.json.top_posts || [],
    }),
    _llm_purpose: 'verification',
  },
};

/**
 * Build LLM Request — provider별 URL/headers/body 생성
 * 입력: system_prompt, user_message, _llm_purpose(optional)
 * 출력: _llm_url, _llm_headers, _llm_body, _llm_provider + 원본 데이터 패스스루
 */

const provider = $env.LLM_PROVIDER || 'gemini';
const systemPrompt = $input.item.json.system_prompt;
const userMessage = $input.item.json.user_message;
const purpose = $input.item.json._llm_purpose || 'content_gen';

const PROVIDERS = {
  gemini: {
    url: `https://generativelanguage.googleapis.com/v1beta/models/gemini-3.6-flash:generateContent`,
    // API 키는 n8n Credential(Header Auth, x-goog-api-key)이 주입한다 —
    // URL/헤더에 넣으면 실행 기록에 평문으로 남는다
    headers: { 'content-type': 'application/json' },
    body: (sys, user, opts) => {
      const payload = {
        contents: [{ role: 'user', parts: [{ text: user }] }],
        systemInstruction: { parts: [{ text: sys }] },
        generationConfig: { maxOutputTokens: opts.maxTokens, temperature: opts.temperature },
      };
      // Search Grounding: 콘텐츠 생성 시 Google 검색으로 실시간 팩트 기반 응답
      if (opts.useSearchGrounding) {
        payload.tools = [{ google_search: {} }];
      }
      return payload;
    },
  },
  claude: {
    url: 'https://api.anthropic.com/v1/messages',
    // API 키는 n8n Credential(Header Auth, x-api-key)이 주입한다.
    // LLM_PROVIDER=claude로 바꿀 때는 LLM Request 노드 2개의 자격증명을
    // 'Claude API Key (Header)'로 함께 바꿔야 한다.
    headers: {
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json',
    },
    body: (sys, user, opts) => ({
      model: opts.model || 'claude-sonnet-4-5-20250514',
      max_tokens: opts.maxTokens,
      temperature: opts.temperature,
      system: sys,
      messages: [{ role: 'user', content: user }],
    }),
  },
};

const config = PROVIDERS[provider];
if (!config) throw new Error(`지원하지 않는 LLM provider: ${provider}`);

const opts = purpose === 'verification'
  ? { maxTokens: 4096, temperature: 0, model: 'claude-haiku-4-5-20251001' }
  : { maxTokens: 32768, temperature: 0.7, useSearchGrounding: true };

return {
  json: {
    _llm_url: config.url,
    _llm_headers: config.headers,
    _llm_body: config.body(systemPrompt, userMessage, opts),
    _llm_provider: provider,
    ...Object.fromEntries(
      Object.entries($input.item.json).filter(([k]) => !k.startsWith('_llm'))
    ),
  }
};

/**
 * Normalize LLM Response (Verify) — provider별 응답에서 텍스트 추출
 * Gemini: candidates[0].content.parts[0].text
 * Claude: content[0].text
 */

const provider = $input.item.json._llm_provider
  || $env.LLM_PROVIDER
  || 'gemini';

let text;
const data = $input.item.json;

if (provider === 'gemini') {
  const parts = data.candidates?.[0]?.content?.parts || [];
  // 추론 모델 + Search Grounding 응답은 텍스트가 여러 part로 분할될 수 있음
  text = parts.filter(p => !p.thought && typeof p.text === 'string').map(p => p.text).join('');
  if (!text) {
    throw new Error(`Gemini 빈 응답 (finishReason: ${data.candidates?.[0]?.finishReason || 'unknown'})`);
  }
} else if (provider === 'claude') {
  text = data.content[0].text;
} else {
  throw new Error(`지원하지 않는 provider 응답: ${provider}`);
}

return { json: { text, _llm_provider: provider } };

/**
 * Parse Verification Result (네이버판) — LLM 판정 + 구조 검사 + 검색 결과 유무를 합쳐 통과 여부 결정
 * Mode: runOnceForEachItem
 * 입력: Normalize Response (Verify) 출력 { text } — 앞 노드 필드는 넘어오지 않으므로 $('노드')로 읽는다
 * 출력: verification { passed, quality_score, reason, llm_reason, 항목별 boolean }
 * 네이버 4개 항목은 LLM이 빠뜨리면 false로 본다(기존 티스토리 판정은 true로 봄 — 네이버는 엄격하게).
 */

const BASE_CHECKS = ['is_accurate', 'is_logical', 'is_complete', 'is_useful', 'is_in_depth'];
const NAVER_CHECKS = ['no_fabricated_experience', 'natural_keyword_use', 'has_unique_info', 'mobile_readable'];
const MIN_QUALITY_SCORE = 70;

// JSON 문자열 정리 (제어 문자 + 유효하지 않은 이스케이프 복구)
function sanitizeJsonStrings(str) {
  const VALID_ESCAPES = '"\\/bfnrtu';
  let result = '';
  let inString = false;
  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    if (inString) {
      if (ch === '\\' && i + 1 < str.length) {
        const next = str[i + 1];
        result += VALID_ESCAPES.includes(next) ? ch + next : '\\\\' + next;
        i++;
        continue;
      }
      if (ch === '"') {
        inString = false;
        result += ch;
        continue;
      }
      const code = ch.charCodeAt(0);
      if (code <= 0x1f) {
        if (code === 0x0a) result += '\\n';
        else if (code === 0x0d) result += '\\r';
        else if (code === 0x09) result += '\\t';
        continue;
      }
      result += ch;
    } else {
      if (ch === '"') inString = true;
      result += ch;
    }
  }
  return result;
}

function parseLlmJson(raw) {
  const match = String(raw || '').match(/\{[\s\S]*\}/);
  if (!match) throw new Error('JSON 없음');
  const cleaned = sanitizeJsonStrings(match[0]).replace(/,\s*([}\]])/g, '$1');
  return JSON.parse(cleaned);
}

function judgeNaver(result, { structurePassed, structureIssues, searchOk }) {
  const reasons = [];
  if (!searchOk) reasons.push('네이버 검색 결과 0건');
  if (!structurePassed) reasons.push(`구조 검사 실패: ${(structureIssues || []).join(', ')}`);
  const failed = [...BASE_CHECKS, ...NAVER_CHECKS].filter((key) => result[key] !== true);
  if (failed.length) reasons.push(`검증 미통과: ${failed.join(', ')}`);
  const score = typeof result.quality_score === 'number' ? result.quality_score : 0;
  if (score < MIN_QUALITY_SCORE) reasons.push(`품질 점수 ${score}점 (최소 ${MIN_QUALITY_SCORE})`);

  const checks = Object.fromEntries([...BASE_CHECKS, ...NAVER_CHECKS].map((k) => [k, result[k] === true]));
  return {
    passed: reasons.length === 0,
    quality_score: score,
    reason: reasons.length ? reasons.join(' / ').slice(0, 300) : (result.reason || ''),
    llm_reason: result.reason || '',
    ...checks,
  };
}

if (typeof $input === 'undefined') {
  module.exports = { parseLlmJson, judgeNaver, BASE_CHECKS, NAVER_CHECKS };
  return;
}

let result;
try {
  result = parseLlmJson($input.item.json.text);
} catch (e) {
  result = { quality_score: 0, reason: `LLM 응답 파싱 실패: ${e.message}` };
}
const structure = $('Validate Structure').item.json.structure_validation
  || { passed: false, issues: ['구조 검사 결과 없음'] };

return {
  json: {
    ...$input.item.json,
    verification: judgeNaver(result, {
      structurePassed: structure.passed === true,
      structureIssues: structure.issues || [],
      searchOk: $('Parse SERP Data').item.json.search_ok === true,
    }),
  },
};

/**
 * Check Duplicate (네이버판) — 티스토리·네이버 두 탭의 발행 키워드와 모두 비교
 * Mode: runOnceForAllItems
 * 키워드 출처는 달라도 분야가 같아 주제가 겹칠 수 있다(설계 문서 3.4).
 */

const OVERLAP_THRESHOLD = 0.7;

function keywordOverlap(kwA, kwB) {
  const tokensA = new Set(kwA.toLowerCase().split(/\s+/).filter((t) => t.length > 0));
  const tokensB = new Set(kwB.toLowerCase().split(/\s+/).filter((t) => t.length > 0));
  // 단일 토큰 키워드: 정확 일치만 판정
  if (tokensA.size < 2 || tokensB.size < 2) {
    return kwA.toLowerCase().trim() === kwB.toLowerCase().trim() ? 1.0 : 0;
  }
  const intersection = [...tokensA].filter((t) => tokensB.has(t));
  const smaller = Math.min(tokensA.size, tokensB.size);
  return smaller > 0 ? intersection.length / smaller : 0;
}

function findDuplicate(keyword, existingKeywords, threshold = OVERLAP_THRESHOLD) {
  let maxOverlap = 0;
  let duplicateOf = '';
  for (const existing of existingKeywords) {
    const overlap = keywordOverlap(keyword, existing);
    if (overlap > maxOverlap) {
      maxOverlap = overlap;
      duplicateOf = existing;
    }
  }
  const isDuplicate = maxOverlap >= threshold;
  return {
    is_duplicate: isDuplicate,
    duplicate_of: isDuplicate ? duplicateOf : '',
    max_overlap: Math.round(maxOverlap * 100) / 100,
    threshold,
  };
}

if (typeof $input === 'undefined') {
  module.exports = { keywordOverlap, findDuplicate };
  return;
}

const keywordsOf = (nodeName) => $(nodeName).all()
  .map((item) => item.json['키워드'] || '')
  .filter((kw) => kw.length > 0);
const existing = [
  ...keywordsOf('Sheets Read (Published Keywords)'),  // 티스토리 탭
  ...keywordsOf('Sheets Read (Naver Published)'),     // 네이버 탭
];

return $input.all().map((item) => ({
  json: { ...item.json, duplicate_check: findDuplicate(item.json['키워드'] || '', existing) },
}));

// Published Keywords 데이터는 $("Sheets Read (Published Keywords)").all()로 접근 가능
// Sheets Read (대기)가 1번만 실행되도록 단일 트리거 아이템 반환
return [{ json: { _trigger: true } }];

/**
 * Fetch Official Docs — 공식문서 본문 크롤링
 * Mode: runOnceForEachItem
 * 입력: Parse SERP Data 출력 (official_urls 포함)
 * 출력: official_docs_text 필드 추가
 *
 * Firecrawl API 키가 있으면 /v1/scrape로 마크다운 추출,
 * 없으면 직접 GET + HTML 텍스트 추출 (fallback)
 */

const FIRECRAWL_KEY = $env.FIRECRAWL_API_KEY || '';
const officialUrls = $input.item.json.official_urls || [];
const MAX_DOCS = 3;
const MAX_CHARS_PER_DOC = 3000;

/**
 * HTML에서 본문 텍스트 추출 (fallback용)
 * <main>, <article>, <div role="main"> 중 첫 매칭 태그의 텍스트 추출
 */
function extractMainText(html) {
  if (typeof html !== 'string') return '';

  // main/article/div[role=main] 태그 내용 추출 시도
  const patterns = [
    /<main[^>]*>([\s\S]*?)<\/main>/i,
    /<article[^>]*>([\s\S]*?)<\/article>/i,
    /<div[^>]*role\s*=\s*["']main["'][^>]*>([\s\S]*?)<\/div>/i,
  ];

  let bodyText = '';
  for (const pattern of patterns) {
    const match = html.match(pattern);
    if (match && match[1]) {
      bodyText = match[1];
      break;
    }
  }

  // 매칭 실패 시 <body> 전체 사용
  if (!bodyText) {
    const bodyMatch = html.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
    bodyText = bodyMatch ? bodyMatch[1] : html;
  }

  // HTML 태그 제거 + 정리
  return bodyText
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<nav[^>]*>[\s\S]*?<\/nav>/gi, '')
    .replace(/<footer[^>]*>[\s\S]*?<\/footer>/gi, '')
    .replace(/<header[^>]*>[\s\S]*?<\/header>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

const docs = [];

for (const entry of officialUrls.slice(0, MAX_DOCS)) {
  try {
    let content = '';

    if (FIRECRAWL_KEY) {
      // Firecrawl API v1/scrape
      const resp = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://api.firecrawl.dev/v1/scrape',
        headers: {
          'Authorization': `Bearer ${FIRECRAWL_KEY}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          url: entry.url,
          formats: ['markdown'],
          onlyMainContent: true,
        }),
        returnFullResponse: false,
        timeout: 15000,
      });

      const parsed = typeof resp === 'string' ? JSON.parse(resp) : resp;
      content = (parsed.data?.markdown || '').slice(0, MAX_CHARS_PER_DOC);
    } else {
      // Fallback: 직접 GET + 텍스트 추출
      const html = await this.helpers.httpRequest({
        method: 'GET',
        url: entry.url,
        timeout: 10000,
        encoding: 'utf-8',
        returnFullResponse: false,
        headers: {
          'User-Agent': 'Mozilla/5.0 (compatible; BlogBot/1.0)',
          'Accept': 'text/html',
        },
      });
      content = extractMainText(html).slice(0, MAX_CHARS_PER_DOC);
    }

    if (content.length > 200) {
      docs.push(`### ${entry.title}\nURL: ${entry.url}\n\n${content}`);
    }
  } catch (e) {
    // 크롤링 실패 시 skip (SERP snippet은 이미 있으므로 치명적이지 않음)
  }
}

const officialDocsText = docs.length > 0
  ? docs.join('\n\n---\n\n')
  : '';

return {
  json: {
    ...$input.item.json,
    official_docs_text: officialDocsText,
  }
};

// 용어 행 N건을 1건으로 축약 — 뒤 노드가 N번 실행되지 않게 한다.
// 용어 데이터는 Route Prompt에서 $('Sheets Read (Brain Terms)')로 참조한다.
return [{ json: { brain_terms_loaded: $input.all().length } }];

// 네이버 발행 키워드 N건을 1건으로 축약
// 키워드는 Check Duplicate에서 $('Sheets Read (Naver Published)')로 참조
return [{ json: { naver_published_loaded: $input.all().length } }];
